#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

std::map<std::size_t, std::vector<std::string>>
GroupByLength(const std::vector<std::string>& words);

int main()
{
    std::string line;
    while (std::getline(std::cin, line))
    {
        std::istringstream in(line);
        std::vector<std::string> words;
        std::string w;
        while (in >> w)
        {
            words.push_back(w);
        }
        auto groups = GroupByLength(words);
        bool firstGroup = true;
        for (const auto& g : groups)
        {
            if (!firstGroup) { std::cout << " "; }
            firstGroup = false;
            std::cout << g.first << ":";
            for (std::size_t i = 0; i < g.second.size(); i++)
            {
                std::cout << (i ? "," : "") << g.second[i];
            }
        }
        std::cout << "\n";
    }
    return 0;
}

