"""Random sentences from a small vocabulary with repeats, so duplicates and
input order inside a group both matter."""

WORDS = ["a", "I", "to", "of", "cat", "dog", "bee", "tree", "frog", "horse",
         "ant", "elephant", "it", "is"]


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(1, 12)
    return {"name": "%d words #%d" % (n, index),
            "stdin": " ".join(rng.choice(WORDS) for _ in range(n)) + "\n"}
